import { createClient } from 'npm:@supabase/supabase-js@2'
import Stripe from 'npm:stripe@17.7.0'
import { isPlanId, priceIdForPlan, type PlanId } from './_shared/stripePlans.ts'
import { checkoutBlockReason } from './_shared/subscriptionRules.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

function jsonResponse(body: Record<string, unknown>, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders,
      'Content-Type': 'application/json',
    },
  })
}

function resolveSiteUrl(req: Request): string {
  const fromEnv = Deno.env.get('SITE_URL')?.replace(/\/+$/, '')
  if (fromEnv) return fromEnv
  const origin = req.headers.get('Origin')?.replace(/\/+$/, '')
  if (origin) return origin
  return 'http://localhost:5173'
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  if (req.method !== 'POST') {
    return jsonResponse({ error: 'Method not allowed' }, 405)
  }

  const stripeSecretKey = Deno.env.get('STRIPE_SECRET_KEY')
  const supabaseUrl = Deno.env.get('SUPABASE_URL')
  const supabaseAnonKey = Deno.env.get('SUPABASE_ANON_KEY')

  const missingKeys: string[] = []
  if (!stripeSecretKey) missingKeys.push('STRIPE_SECRET_KEY')
  if (!supabaseUrl) missingKeys.push('SUPABASE_URL')
  if (!supabaseAnonKey) missingKeys.push('SUPABASE_ANON_KEY')

  if (missingKeys.length > 0) {
    return jsonResponse({ error: 'Server is not configured', missingKeys }, 500)
  }

  const authHeader = req.headers.get('Authorization')
  if (!authHeader) {
    return jsonResponse({ error: 'Unauthorized' }, 401)
  }

  let body: { planId?: string }
  try {
    body = (await req.json()) as { planId?: string }
  } catch {
    return jsonResponse({ error: 'Invalid JSON body' }, 400)
  }

  const planId = body.planId
  if (!planId || !isPlanId(planId)) {
    return jsonResponse({ error: 'planId must be light, pro, or enterprise' }, 400)
  }

  const priceId = priceIdForPlan(planId as PlanId)
  if (!priceId) {
    return jsonResponse(
      {
        error: 'Stripe price is not configured for this plan',
        missingKeys: [`STRIPE_PRICE_${planId.toUpperCase()}`],
      },
      500,
    )
  }

  const supabase = createClient(supabaseUrl!, supabaseAnonKey!, {
    global: { headers: { Authorization: authHeader } },
  })

  const {
    data: { user },
    error: userError,
  } = await supabase.auth.getUser()

  if (userError || !user) {
    return jsonResponse({ error: 'Unauthorized' }, 401)
  }

  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
  if (!serviceRoleKey) {
    return jsonResponse({ error: 'Server is not configured', missingKeys: ['SUPABASE_SERVICE_ROLE_KEY'] }, 500)
  }

  const admin = createClient(supabaseUrl!, serviceRoleKey)

  const { data: existingSubscription, error: existingSubError } = await admin
    .from('billing_subscriptions')
    .select('plan_id, status, current_period_end, cancel_at_period_end')
    .eq('user_id', user.id)
    .maybeSingle()

  if (existingSubError) {
    return jsonResponse({ error: existingSubError.message }, 500)
  }

  const checkoutDenied = checkoutBlockReason(existingSubscription, planId as PlanId)
  if (checkoutDenied) {
    return jsonResponse({ error: checkoutDenied, code: 'checkout_not_allowed' }, 400)
  }

  const { data: profile, error: profileError } = await admin
    .from('profiles')
    .select('stripe_customer_id, display_name')
    .eq('id', user.id)
    .maybeSingle()

  if (profileError) {
    return jsonResponse({ error: profileError.message }, 500)
  }

  const stripe = new Stripe(stripeSecretKey!)

  let customerId = profile?.stripe_customer_id ?? null

  if (!customerId) {
    const customer = await stripe.customers.create({
      email: user.email ?? undefined,
      name: profile?.display_name ?? undefined,
      metadata: { user_id: user.id },
    })
    customerId = customer.id

    const { error: updateProfileError } = await admin
      .from('profiles')
      .update({ stripe_customer_id: customerId })
      .eq('id', user.id)

    if (updateProfileError) {
      return jsonResponse({ error: updateProfileError.message }, 500)
    }
  }

  const siteUrl = resolveSiteUrl(req)

  const session = await stripe.checkout.sessions.create({
    mode: 'subscription',
    customer: customerId,
    client_reference_id: user.id,
    line_items: [{ price: priceId, quantity: 1 }],
    metadata: {
      user_id: user.id,
      plan_id: planId,
    },
    subscription_data: {
      metadata: {
        user_id: user.id,
        plan_id: planId,
      },
    },
    success_url: `${siteUrl}/billing?checkout=success&plan=${planId}`,
    cancel_url: `${siteUrl}/billing?checkout=cancel&plan=${planId}`,
  })

  if (!session.url) {
    return jsonResponse({ error: 'Stripe did not return checkout URL' }, 502)
  }

  return jsonResponse({ url: session.url })
})

export type PlanId = 'light' | 'pro' | 'enterprise'

const PLAN_IDS: PlanId[] = ['light', 'pro', 'enterprise']

export function isPlanId(value: string): value is PlanId {
  return (PLAN_IDS as string[]).includes(value)
}

export function priceIdForPlan(planId: PlanId): string | null {
  const envKey =
    planId === 'light'
      ? 'STRIPE_PRICE_LIGHT'
      : planId === 'pro'
        ? 'STRIPE_PRICE_PRO'
        : 'STRIPE_PRICE_ENTERPRISE'
  return Deno.env.get(envKey) ?? null
}

export function planIdForPriceId(priceId: string): PlanId | null {
  for (const planId of PLAN_IDS) {
    const mapped = priceIdForPlan(planId)
    if (mapped && mapped === priceId) return planId
  }
  return null
}

export function resolvePlanIdFromMetadata(metadata: Record<string, string> | null | undefined): PlanId | null {
  const raw = metadata?.plan_id
  if (raw && isPlanId(raw)) return raw
  return null
}

import { isPlanId, type PlanId } from './stripePlans.ts'

const PLAN_RANK: Record<PlanId, number> = {
  light: 1,
  pro: 2,
  enterprise: 3,
}

export function planRank(planId: string | null | undefined): number {
  if (!planId || !isPlanId(planId)) return 0
  return PLAN_RANK[planId]
}

export type SubscriptionRow = {
  plan_id: string
  status: string
  current_period_end: string | null
  cancel_at_period_end?: boolean
}

export function isSubscriptionEntitled(subscription: SubscriptionRow | null): boolean {
  if (!subscription) return false

  const status = subscription.status
  if (status !== 'active' && status !== 'trialing') return false

  if (subscription.current_period_end) {
    const end = new Date(subscription.current_period_end)
    if (end.getTime() <= Date.now()) return false
  }

  return true
}

export function checkoutBlockReason(
  subscription: SubscriptionRow | null,
  _targetPlanId: PlanId,
): string | null {
  if (!isSubscriptionEntitled(subscription)) return null

  if (subscription!.cancel_at_period_end) {
    return 'Подписка уже отменена и действует до конца оплаченного периода. Более дешёвый тариф можно оформить после этой даты.'
  }

  return 'У вас уже есть активная подписка. Новую оплату можно оформить только после отмены и окончания текущего периода, либо повысьте тариф.'
}

export function upgradeBlockReason(
  subscription: SubscriptionRow | null,
  targetPlanId: PlanId,
): string | null {
  if (!subscription?.plan_id) {
    return 'Сначала оформите подписку.'
  }

  if (!isSubscriptionEntitled(subscription)) {
    return 'Активная подписка не найдена. Оформите тариф через оплату.'
  }

  const currentRank = planRank(subscription.plan_id)
  const targetRank = planRank(targetPlanId)

  if (targetRank <= currentRank) {
    return 'Понижение тарифа недоступно при активной подписке. Отмените её и дождитесь окончания периода.'
  }

  return null
}

export function cancelBlockReason(
  subscription: (SubscriptionRow & { stripe_subscription_id?: string }) | null,
): string | null {
  if (!subscription?.stripe_subscription_id) {
    return 'Нет подписки для отмены.'
  }

  if (!isSubscriptionEntitled(subscription)) {
    return 'Подписка уже неактивна.'
  }

  if (subscription.cancel_at_period_end) {
    return null
  }

  return null
}
